/**
 * A compact sRGB colour profile (ICC version 2, 456 bytes), from Clinton Ingram's
 * Compact ICC Profiles (CC0 1.0, https://github.com/saucecontrol/Compact-ICC-Profiles).
 * PDF/A files name it as their output intent.
 */
const BASE64 =
  '';

export function srgbProfile(): Uint8Array {
  return Uint8Array.from(atob(BASE64), (c) => c.charCodeAt(0));
}
